"""clamp functions used by the grader. Do not edit this file.

`correct` limits x to the range low..high and raises ValueError when low > high.
The others each contain one bug.
"""


def correct(x, low, high):
    if low > high:
        raise ValueError("low must not be greater than high")
    if x < low:
        return low
    if x > high:
        return high
    return x


def bug_no_upper_limit(x, low, high):
    if low > high:
        raise ValueError("low must not be greater than high")
    return max(x, low)


def bug_no_lower_limit(x, low, high):
    if low > high:
        raise ValueError("low must not be greater than high")
    return min(x, high)


def bug_no_range_check(x, low, high):
    if x < low:
        return low
    if x > high:
        return high
    return x


def bug_equal_bounds_rejected(x, low, high):
    if low >= high:
        raise ValueError("low must be less than high")
    if x < low:
        return low
    if x > high:
        return high
    return x


def bug_truncates_floats(x, low, high):
    if low > high:
        raise ValueError("low must not be greater than high")
    if x < low:
        return low
    if x > high:
        return high
    return int(x)


def bug_moves_edge_values(x, low, high):
    if low > high:
        raise ValueError("low must not be greater than high")
    if x <= low:
        return low + 1
    if x >= high:
        return high
    return x
